const res = await helpers.httpRequest({ method:'GET', url:'http://localhost:3000/api/issues?limit=2000' });
const items = Array.isArray(res) ? res : (res.issues || []);
const features = items.filter(i => i.type==='feature' && i.status==='open');
const changed = [];
for (const f of features) {
  const children = items.filter(i => i.parent_id === f.id && ['task','bug'].includes(i.type));
  if (!children.length) continue;
  const active = children.filter(c => !['closed','released','completed','cancelled'].includes(c.status));
  const allPassed = children.every(c => c.test_status === 'passed' || ['released','completed','closed'].includes(c.status));
  if (active.length === 0 && allPassed) {
    changed.push(f.task_key);
  }
}
return [{ json: { action: changed.length ? 'ready_for_review' : 'idle', count: changed.length, features: changed.slice(0,25) } }];
